import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { readFile } from "node:fs/promises";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
  foundationMigration,
  requireTestDatabaseUrl,
} from "./helpers/foundation-db";

describe("foundation database target guard", () => {
  it("rejects non-test or remote targets before writes", () => {
    for (const url of [
      "postgresql://localhost/mailloop",
      "postgresql://example.com/mailloop_test",
      "postgresql://127.0.0.1/mailloop_test_backup",
    ])
      expect(() => requireTestDatabaseUrl(url)).toThrow("local _test");
    expect(
      requireTestDatabaseUrl("postgresql://localhost/mailloop_test").hostname,
    ).toBe("localhost");
  });
});

describe.runIf(databaseTestsEnabled)(
  "subscription foundation additive migration",
  () => {
    let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>;
    let legacy: Record<string, Record<string, unknown>[]>;
    let oldColumns: unknown[];
    let oldTables: string[];
    const query = (sql: string, values?: unknown[]) =>
      fixture.client.query(sql, values);
    beforeAll(async () => {
      fixture = await createIsolatedDatabase();
      try {
        for (const migration of fixture.migrations.filter(
          (name) => name < foundationMigration,
        ))
          await fixture.apply(migration);
        await query(`
        INSERT INTO "User" (id,email,"encryptedRefreshToken","gmailAuthorized","followUpDays")
        VALUES ('owner','[REDACTED_EMAIL]','fixture-ciphertext',true,14),('other','[REDACTED_EMAIL]',NULL,false,0);
        INSERT INTO "Template" (id,"userId",name,subject,body)
        VALUES ('template','owner','Legacy','Hello','Fixture body');
        INSERT INTO "Contact" (id,"userId",name,email) VALUES ('contact','owner','Ada','[REDACTED_EMAIL]');
        INSERT INTO "Campaign" (id,"userId","templateId",status) VALUES ('campaign','owner','template','COMPLETED');
        INSERT INTO "Send" (id,"campaignId","contactId",status,"deliveryState","sentAt",body)
        VALUES ('send','campaign','contact','SENT','DONE',CURRENT_TIMESTAMP,'Fixture snapshot');
        INSERT INTO "DeliveryReceipt" (id,"userId","recipientEmail","createdAt","sentAt")
        VALUES ('receipt','owner','[REDACTED_EMAIL]',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
      `);
        legacy = {};
        for (const table of [
          "User",
          "Template",
          "Contact",
          "Campaign",
          "Send",
          "DeliveryReceipt",
        ])
          legacy[table] = (
            await query(`SELECT * FROM "${table}" ORDER BY id`)
          ).rows;
        oldColumns = (
          await query(
            `SELECT table_name,column_name,data_type,datetime_precision FROM information_schema.columns WHERE table_schema=$1 ORDER BY table_name,ordinal_position`,
            [fixture.schema],
          )
        ).rows;
        oldTables = (
          await query(`SELECT tablename FROM pg_tables WHERE schemaname=$1`, [
            fixture.schema,
          ])
        ).rows.map((row) => row.tablename);
        await fixture.apply(foundationMigration);
      } catch (error) {
        await fixture.cleanup();
        throw error;
      }
    });
    afterAll(async () => {
      if (fixture) await fixture.cleanup();
    });

    async function rejects(sql: string, constraint: string, code = "23514") {
      await expect(query(sql)).rejects.toMatchObject({ code, constraint });
    }
    it("preserves all legacy data and supplies safe defaults to old and future users", async () => {
      for (const [table, rows] of Object.entries(legacy)) {
        const actual = (await query(`SELECT * FROM "${table}" ORDER BY id`))
          .rows;
        if (table === "User")
          rows.forEach((row, index) =>
            expect(actual[index]).toMatchObject(row),
          );
        else expect(actual).toEqual(rows);
      }
      await query(
        `INSERT INTO "User" (id,email) VALUES ('future','[REDACTED_EMAIL]')`,
      );
      const defaults = {
        plan: "FREE",
        subscriptionStatus: "NONE",
        cancelAtPeriodEnd: false,
        billingStateVersion: 0,
        isAdmin: false,
        isSuspended: false,
        currentPeriodStart: null,
        currentPeriodEnd: null,
        dodoCustomerId: null,
        dodoSubscriptionId: null,
        gracePeriodEnd: null,
        billingCountry: null,
        billingCurrency: null,
        lastBillingEventAt: null,
        planOverride: null,
        planOverrideStartsAt: null,
        planOverrideExpiresAt: null,
        planOverrideReason: null,
        grandfatheredUntil: null,
        freeTemplateId: null,
        suspendedAt: null,
        suspensionReason: null,
        lastActiveAt: null,
      };
      for (const id of ["owner", "future"])
        expect(
          (await query('SELECT * FROM "User" WHERE id=$1', [id])).rows[0],
        ).toMatchObject(defaults);
      expect((await query('SELECT * FROM "BillingSubscription"')).rows).toEqual(
        [],
      );
    });
    it("seeds exactly one global control row with gating disabled", async () => {
      expect((await query('SELECT * FROM "SystemControl"')).rows).toEqual([
        {
          id: expect.stringMatching(/^[0-9a-f-]{36}$/),
          key: "global",
          sendingEnabled: true,
          paidGatingEnabled: false,
          updatedAt: expect.any(Date),
        },
      ]);
      await rejects(
        `INSERT INTO "SystemControl" VALUES ('duplicate','global',true,false,now())`,
        "SystemControl_key_key",
        "23505",
      );
      await rejects(
        `INSERT INTO "SystemControl" VALUES ('wrong','other',true,false,now())`,
        "SystemControl_global_key_check",
      );
    });
    it("enforces every User check and accepts atomic boundary updates", async () => {
      const invalid = [
        ["period_bounds", `"currentPeriodStart"=now()`],
        ["period_bounds", `"currentPeriodEnd"=now()`],
        [
          "period_bounds",
          `"currentPeriodStart"=now(),"currentPeriodEnd"=now()`,
        ],
        ["grace_bounds", `"gracePeriodEnd"=now()`],
        [
          "grace_bounds",
          `"currentPeriodStart"='2026-10-01',"currentPeriodEnd"='2026-11-01',"gracePeriodEnd"='2026-10-31'`,
        ],
        ["billing_version", `"billingStateVersion"=-1`],
        ["country", `"billingCountry"='us'`],
        ["currency", `"billingCurrency"='US'`],
        ["override", `"planOverride"='PAID'`],
        ["override", `"planOverrideReason"='reason'`],
        [
          "override",
          `"planOverride"='PAID',"planOverrideStartsAt"=now(),"planOverrideReason"=' '`,
        ],
        [
          "override",
          `"planOverride"='PAID',"planOverrideStartsAt"=now(),"planOverrideExpiresAt"=now(),"planOverrideReason"='reason'`,
        ],
        ["suspension", `"isSuspended"=true`],
        ["suspension", `"suspendedAt"=now()`],
        [
          "suspension",
          `"isSuspended"=true,"suspendedAt"=now(),"suspensionReason"=' '`,
        ],
      ];
      for (const [name, patch] of invalid)
        await rejects(
          `UPDATE "User" SET ${patch} WHERE id='owner'`,
          `User_${name}_check`,
        );
      await query(
        `UPDATE "User" SET "currentPeriodStart"='2026-10-01',"currentPeriodEnd"='2026-11-01',"gracePeriodEnd"='2026-11-01',"billingStateVersion"=0,"billingCountry"='US',"billingCurrency"='USD',"planOverride"='FREE',"planOverrideStartsAt"=now(),"planOverrideReason"='Support grant',"isSuspended"=true,"suspendedAt"=now(),"suspensionReason"='Reviewed' WHERE id='other'`,
      );
      await query(
        `UPDATE "User" SET "planOverrideExpiresAt"=now()+interval '1 second' WHERE id='other'`,
      );
    });
    it("enforces subscription checks, uniqueness and FK ownership", async () => {
      await query(
        `INSERT INTO "BillingSubscription" (id,"userId","dodoSubscriptionId","dodoCustomerId","productId",status,"updatedAt") VALUES ('sub','owner','provider-sub','customer','product','PENDING',now())`,
      );
      for (const [name, patch] of [
        ["period_bounds", `"periodEnd"=now()`],
        ["period_bounds", `"periodStart"=now(),"periodEnd"=now()`],
        ["grace_bounds", `"gracePeriodEnd"=now()`],
        ["amount", `"recurringAmountMinor"=-1`],
        ["currency", `currency='usd'`],
        ["country", `"billingCountry"='USA'`],
      ])
        await rejects(
          `UPDATE "BillingSubscription" SET ${patch} WHERE id='sub'`,
          `BillingSubscription_${name}_check`,
        );
      await query(
        `UPDATE "BillingSubscription" SET "periodStart"='2026-10-01',"periodEnd"='2026-11-01',"gracePeriodEnd"='2026-11-01',"recurringAmountMinor"=0,currency='USD',"billingCountry"='US' WHERE id='sub'`,
      );
      await rejects(
        `UPDATE "BillingSubscription" SET "gracePeriodEnd"='2026-10-31' WHERE id='sub'`,
        "BillingSubscription_grace_bounds_check",
      );
      await rejects(
        `INSERT INTO "BillingSubscription" SELECT 'sub2',"userId","dodoSubscriptionId","dodoCustomerId","productId",status,"periodStart","periodEnd","gracePeriodEnd","cancelAtPeriodEnd",currency,"billingCountry","recurringAmountMinor","lastEventAt","createdAt","updatedAt" FROM "BillingSubscription" WHERE id='sub'`,
        "BillingSubscription_dodoSubscriptionId_key",
        "23505",
      );
      await rejects(
        `UPDATE "BillingSubscription" SET "userId"='missing' WHERE id='sub'`,
        "BillingSubscription_userId_fkey",
        "23503",
      );
      for (const field of ["dodoCustomerId", "dodoSubscriptionId"]) {
        await query(`UPDATE "User" SET "${field}"='external' WHERE id='owner'`);
        await rejects(
          `UPDATE "User" SET "${field}"='external' WHERE id='other'`,
          `User_${field}_key`,
          "23505",
        );
      }
    });
    it("enforces checkout bounds and owner-scoped idempotency", async () => {
      await query(
        `INSERT INTO "CheckoutAttempt" (id,"userId","idempotencyKey","productId","billingCountry","billingCurrency","dodoSessionId","createdAt","expiresAt") VALUES ('checkout','owner','request','product','US','USD','session',now(),now()+interval '1 millisecond')`,
      );
      for (const [name, patch] of [
        ["expiry", `"expiresAt"="createdAt"`],
        ["country", `"billingCountry"='us'`],
        ["currency", `"billingCurrency"='US'`],
        ["status", `status=' '`],
      ])
        await rejects(
          `UPDATE "CheckoutAttempt" SET ${patch} WHERE id='checkout'`,
          `CheckoutAttempt_${name}_check`,
        );
      await rejects(
        `INSERT INTO "CheckoutAttempt" (id,"userId","idempotencyKey","productId","billingCountry","billingCurrency","expiresAt") VALUES ('duplicate','owner','request','product','US','USD',now()+interval '1 day')`,
        "CheckoutAttempt_userId_idempotencyKey_key",
        "23505",
      );
      await query(
        `INSERT INTO "CheckoutAttempt" (id,"userId","idempotencyKey","productId","billingCountry","billingCurrency","expiresAt") VALUES ('other-checkout','other','request','product','US','USD',now()+interval '1 day')`,
      );
      await rejects(
        `UPDATE "CheckoutAttempt" SET "dodoSessionId"='session' WHERE id='other-checkout'`,
        "CheckoutAttempt_dodoSessionId_key",
        "23505",
      );
      await rejects(
        `UPDATE "CheckoutAttempt" SET "userId"='missing' WHERE id='checkout'`,
        "CheckoutAttempt_userId_fkey",
        "23503",
      );
    });
    it("checks normalized webhook object data, hashes, versions and retry counters", async () => {
      await query(
        `INSERT INTO "BillingWebhookEvent" (id,"webhookId","eventType","businessId","occurredAt","normalizedData","payloadHash") VALUES ('event','webhook','type','business',now(),'{}',repeat('a',64))`,
      );
      for (const [name, patch] of [
        ["attempts", `attempts=-1`],
        ["processing_version", `"processingVersion"=0`],
        ["state", `state=' '`],
        ["data", `"normalizedData"='[]'`],
        ["data", `"normalizedData"='null'`],
        ["hash", `"payloadHash"=repeat('A',64)`],
        ["hash", `"payloadHash"=repeat('a',63)`],
      ])
        await rejects(
          `UPDATE "BillingWebhookEvent" SET ${patch} WHERE id='event'`,
          `BillingWebhookEvent_${name}_check`,
        );
      await query(
        `UPDATE "BillingWebhookEvent" SET attempts=0,"processingVersion"=1,state='FUTURE_STATE',"normalizedData"='{"allowed":"metadata"}' WHERE id='event'`,
      );
      await rejects(
        `INSERT INTO "BillingWebhookEvent" (id,"webhookId","eventType","businessId","occurredAt","normalizedData","payloadHash") VALUES ('duplicate','webhook','type','business',now(),'{}',repeat('a',64))`,
        "BillingWebhookEvent_webhookId_key",
        "23505",
      );
    });
    it("retains audit snapshots through SET NULL and cascades user-owned billing rows", async () => {
      await query(
        `INSERT INTO "AdminAuditLog" (id,"actorUserId","targetUserId","actorIdSnapshot","targetIdSnapshot",action,"requestId",reason,before,after) VALUES ('audit','other','owner','other','owner','OVERRIDE','audit-request','Support','{}','{}')`,
      );
      for (const [name, patch] of [
        ["actor_snapshot", `"actorIdSnapshot"=' '`],
        ["target_snapshot", `"targetIdSnapshot"=NULL`],
        ["target_snapshot", `"targetIdSnapshot"=' '`],
        ["action", `action=' '`],
        ["reason", `reason=' '`],
        ["before", `before='[]'`],
        ["after", `after='null'`],
      ])
        await rejects(
          `UPDATE "AdminAuditLog" SET ${patch} WHERE id='audit'`,
          `AdminAuditLog_${name}_check`,
        );
      await rejects(
        `INSERT INTO "AdminAuditLog" (id,"actorIdSnapshot",action,"requestId",reason,before,after) VALUES ('duplicate','other','ACTION','audit-request','Support','{}','{}')`,
        "AdminAuditLog_requestId_key",
        "23505",
      );
      await rejects(
        `UPDATE "AdminAuditLog" SET "actorUserId"='missing' WHERE id='audit'`,
        "AdminAuditLog_actorUserId_fkey",
        "23503",
      );
      await rejects(
        `UPDATE "AdminAuditLog" SET "targetUserId"='missing' WHERE id='audit'`,
        "AdminAuditLog_targetUserId_fkey",
        "23503",
      );
      await query(
        `DELETE FROM "Campaign" WHERE "userId" IN ('owner','other'); DELETE FROM "User" WHERE id IN ('owner','other')`,
      );
      expect((await query('SELECT * FROM "BillingSubscription"')).rows).toEqual(
        [],
      );
      expect((await query('SELECT * FROM "CheckoutAttempt"')).rows).toEqual([]);
      expect(
        (await query('SELECT * FROM "AdminAuditLog"')).rows[0],
      ).toMatchObject({
        actorUserId: null,
        targetUserId: null,
        actorIdSnapshot: "other",
        targetIdSnapshot: "owner",
      });
      expect(
        (
          await query(
            'SELECT count(*)::int AS count FROM "BillingWebhookEvent"',
          )
        ).rows[0].count,
      ).toBe(1);
    });
    it("adds only planned tables, fields and indexes with TEXT IDs and TIMESTAMP(3) dates", async () => {
      const columns = (
        await query(
          `SELECT table_name,column_name,data_type,datetime_precision FROM information_schema.columns WHERE table_schema=$1 ORDER BY table_name,ordinal_position`,
          [fixture.schema],
        )
      ).rows;
      for (const old of oldColumns) expect(columns).toContainEqual(old);
      const newTables = [
        "BillingSubscription",
        "CheckoutAttempt",
        "BillingWebhookEvent",
        "AdminAuditLog",
        "SystemControl",
      ];
      const tables = (
        await query(`SELECT tablename FROM pg_tables WHERE schemaname=$1`, [
          fixture.schema,
        ])
      ).rows.map((r) => r.tablename);
      expect(tables.sort()).toEqual([...oldTables, ...newTables].sort());
      const sql = await readFile(
        `prisma/migrations/${foundationMigration}/migration.sql`,
        "utf8",
      );
      const expectedIndexes = [
        ...sql.matchAll(/CREATE (?:UNIQUE )?INDEX "([^"]+)"/g),
      ].map((m) => m[1]);
      const indexes = (
        await query(`SELECT indexname FROM pg_indexes WHERE schemaname=$1`, [
          fixture.schema,
        ])
      ).rows.map((r) => r.indexname);
      for (const name of expectedIndexes) expect(indexes).toContain(name);
      for (const column of columns.filter((c) =>
        newTables.includes(c.table_name),
      )) {
        if (column.column_name === "id" || column.column_name.endsWith("Id"))
          expect(column.data_type).toBe("text");
        if (column.data_type === "timestamp without time zone")
          expect(column.datetime_precision).toBe(3);
      }
      const newUserColumns = columns.filter(
        (c) =>
          c.table_name === "User" &&
          !oldColumns.some((old) => JSON.stringify(old) === JSON.stringify(c)),
      );
      expect(newUserColumns.map((c) => c.column_name).sort()).toEqual(
        [
          "plan",
          "subscriptionStatus",
          "currentPeriodStart",
          "currentPeriodEnd",
          "dodoCustomerId",
          "dodoSubscriptionId",
          "cancelAtPeriodEnd",
          "gracePeriodEnd",
          "billingCountry",
          "billingCurrency",
          "billingStateVersion",
          "lastBillingEventAt",
          "planOverride",
          "planOverrideStartsAt",
          "planOverrideExpiresAt",
          "planOverrideReason",
          "grandfatheredUntil",
          "freeTemplateId",
          "isAdmin",
          "isSuspended",
          "suspendedAt",
          "suspensionReason",
          "lastActiveAt",
        ].sort(),
      );
      expect(columns.filter((c) => c.table_name === "Send")).toEqual(
        oldColumns.filter(
          (c) => (c as { table_name: string }).table_name === "Send",
        ),
      );
      // Coverage guard: each hand-maintained CHECK is named in this test file.
      const source = await readFile(
        "tests/subscription-foundation-migration.db.test.ts",
        "utf8",
      );
      const checks = [...sql.matchAll(/ADD CONSTRAINT "([^"]+)_check"/g)].map(
        (m) => m[1],
      );
      expect(checks).toHaveLength(28);
      for (const name of checks)
        expect(source).toContain(name.split("_").slice(1).join("_"));
    });
  },
);
